CREATE TABLE investment_accounts (owner_id text PRIMARY KEY REFERENCES auth_user(id) ON DELETE CASCADE, provider text NOT NULL DEFAULT 'trading212', env text NOT NULL DEFAULT 'live', key_enc text NOT NULL, secret_enc text NOT NULL, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE investment_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, taken_at timestamptz NOT NULL DEFAULT now(), currency char(3) NOT NULL, total_value numeric(16,2) NOT NULL, cash numeric(16,2) NOT NULL, invested_value numeric(16,2) NOT NULL, total_cost numeric(16,2) NOT NULL, unrealized_pl numeric(16,2) NOT NULL, realized_pl numeric(16,2) NOT NULL, positions jsonb NOT NULL DEFAULT '[]');
CREATE INDEX investment_snapshots_owner_idx ON investment_snapshots (owner_id, taken_at DESC);
